"""AI alignment evaluation: monitor flag statistics over model transcripts."""


def monitor_flag_rate(events):
    """The share of transcripts whose ``flagged`` value is exactly True."""
    if not events:
        return 0.0
    hits = sum(1 for event in events if event["flagged"] is True)
    return hits / len(events)


def pooled_flag_rate(groups):
    """The transcript-weighted flag rate across groups."""
    total = sum(len(events) for events in groups.values())
    if total == 0:
        return 0.0
    flagged = sum(
        1
        for events in groups.values()
        for event in events
        if event["flagged"] is True
    )
    return flagged / total


def flags_in_window(daily_counts, days):
    """Sum the last ``days`` entries of oldest-first daily counts."""
    if days <= 0:
        return 0
    return sum(daily_counts[-days:])


def flag_rate_by_group(groups):
    """Return each group's flag rate, with empty groups mapped to None."""
    return {
        name: monitor_flag_rate(groups[name]) if groups[name] else None
        for name in sorted(groups)
    }


def longest_flag_streak(daily_counts):
    """Return the longest run of entries greater than zero."""
    best = cur = 0
    for count in daily_counts:
        if count > 0:
            cur += 1
            best = max(best, cur)
        else:
            cur = 0
    return best

"""Load and normalize safety-monitor transcript logs."""


def parse_transcript_log(lines):
    """Parse transcript log lines according to SPEC.md section 4."""
    out = []
    for line_number, line in enumerate(lines, start=1):
        stripped = line.strip()
        if not stripped or stripped.startswith("#"):
            continue

        fields = [field.strip() for field in line.split(",")]
        if len(fields) != 3:
            raise ValueError(f"line {line_number}: expected exactly three fields")
        id_, day_text, flag_text = fields
        try:
            day = int(day_text)
        except ValueError as exc:
            raise ValueError(f"line {line_number}: day must be an integer") from exc

        if flag_text == "1":
            flagged = True
        elif flag_text == "0":
            flagged = False
        elif flag_text == "":
            flagged = None
        else:
            raise ValueError(f"line {line_number}: flagged must be 1, 0, or empty")

        out.append({"id": id_, "day": day, "flagged": flagged})
    return out


def dedupe_transcripts(events):
    """Keep the last record per id, sorted by day then id."""
    latest_by_id = {}
    for event in events:
        latest_by_id[event["id"]] = event
    return sorted(latest_by_id.values(), key=lambda event: (event["day"], event["id"]))


def daily_flag_counts(events, start_day, end_day):
    """Count flagged transcripts for every day in the inclusive range."""
    if end_day < start_day:
        return []

    counts = [0] * (end_day - start_day + 1)
    for event in events:
        day = event["day"]
        if start_day <= day <= end_day and event["flagged"] is True:
            counts[day - start_day] += 1
    return counts

import pytest

from safety_evals.loader import daily_flag_counts, dedupe_transcripts, parse_transcript_log
from safety_evals.metrics import (
    flag_rate_by_group,
    flags_in_window,
    longest_flag_streak,
    monitor_flag_rate,
    pooled_flag_rate,
)
from safety_evals.report import monitor_summary, top_flagged_groups


def test_monitor_flag_rate_basic():
    assert monitor_flag_rate([{"flagged": True}, {"flagged": False}]) == 0.5


def test_monitor_flag_rate_none_is_not_flagged():
    assert monitor_flag_rate([{"flagged": True}, {"flagged": None}, {"flagged": False}]) == 1 / 3
    assert monitor_flag_rate([]) == 0.0


def test_pooled_flag_rate_weights_transcripts_not_groups():
    groups = {
        "large": [{"flagged": True}, {"flagged": False}, {"flagged": False}],
        "small": [{"flagged": True}],
        "empty": [],
    }
    assert pooled_flag_rate(groups) == 0.5
    assert pooled_flag_rate({"empty": []}) == 0.0


def test_flags_in_window():
    assert flags_in_window([1, 2, 3], 2) == 5
    assert flags_in_window([1, 2, 3], 0) == 0
    assert flags_in_window([1, 2], 5) == 3


def test_parse_transcript_log_flag_values_and_skipped_lines():
    assert parse_transcript_log([
        "  # comment",
        "  ",
        " x1 , 3 , 1 ",
        "x2,4,0",
        "x3,5,",
    ]) == [
        {"id": "x1", "day": 3, "flagged": True},
        {"id": "x2", "day": 4, "flagged": False},
        {"id": "x3", "day": 5, "flagged": None},
    ]


@pytest.mark.parametrize("line", ["x,not-a-day,1", "x,1", "x,1,0,extra"])
def test_parse_transcript_log_errors_include_input_line(line):
    with pytest.raises(ValueError, match="line 2"):
        parse_transcript_log(["# ignored", line])


def test_dedupe_transcripts_keeps_last_duplicate_and_sorts():
    events = [
        {"id": "b", "day": 2, "flagged": True},
        {"id": "a", "day": 3, "flagged": False},
        {"id": "b", "day": 1, "flagged": False},
    ]
    assert dedupe_transcripts(events) == [events[2], events[1]]


def test_daily_flag_counts_inclusive_range_and_empty_range():
    events = [
        {"id": "a", "day": 1, "flagged": True},
        {"id": "b", "day": 2, "flagged": True},
        {"id": "c", "day": 2, "flagged": None},
        {"id": "d", "day": 4, "flagged": True},
    ]
    assert daily_flag_counts(events, 2, 4) == [1, 0, 1]
    assert daily_flag_counts(events, 5, 3) == []


def test_monitor_summary_spec_fields_and_rounding():
    events = [
        {"id": "a", "day": 1, "flagged": True},
        {"id": "b", "day": 2, "flagged": False},
        {"id": "c", "day": 3, "flagged": True},
    ]
    assert monitor_summary({"g": events, "empty": []}, 1) == {
        "rate": 0.667,
        "recent": 1,
        "groups": 1,
    }
    assert monitor_summary({"empty": []}, 2) == {"rate": 0.0, "recent": 0, "groups": 0}


def test_top_flagged_groups_and_flag_rate_by_group():
    groups = {
        "z": [{"flagged": True}],
        "a": [{"flagged": True}],
        "middle": [{"flagged": True}, {"flagged": False}],
        "empty": [],
    }
    assert top_flagged_groups(groups, 3) == ["a", "z", "middle"]
    assert flag_rate_by_group(groups) == {"a": 1.0, "empty": None, "middle": 0.5, "z": 1.0}


def test_longest_flag_streak_requires_positive_counts():
    assert longest_flag_streak([0, 1, 2, 0, -1, 1]) == 2
    assert longest_flag_streak([]) == 0
